'use strict';
var stocks=window.__MARKET_DATA__.stocks, sectors=window.__MARKET_DATA__.sectors, summary=window.__MARKET_DATA__.summary;
summary.age_days=Math.max(summary.age_days,Math.floor((Date.now()-Date.parse(summary.as_of.slice(0,4)+'-'+summary.as_of.slice(4,6)+'-'+summary.as_of.slice(6)+'T15:00:00+08:00'))/86400000));
const byId=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(value,digits=2)=>value==null||!Number.isFinite(Number(value))?'—':Number(value).toLocaleString('zh-CN',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const dateText=value=>/^\d{8}$/.test(String(value))?`${value.slice(0,4)}-${value.slice(4,6)}-${value.slice(6)}`:value||'—';
const color=value=>value>0?'up':value<0?'down':'';
const charts={};let selectedStock=null,chartRequest=0,stockPage=0,filterIndustry='';
const historyCache=new Map();
function localRead(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}}
let watch=localRead('marketWatch',{stocks:[],sectors:[]});
if(typeof watch!=='object'||Array.isArray(watch))watch={stocks:[],sectors:[]};
if(!Array.isArray(watch.stocks))watch.stocks=[];if(!Array.isArray(watch.sectors))watch.sectors=[];
function showView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.view===id));if(id==='watchView')renderWatch();requestAnimationFrame(()=>Object.values(charts).forEach(c=>c.resize()))}
document.querySelector('.tabs').addEventListener('click',event=>{const tab=event.target.closest('[data-view]');if(tab)showView(tab.dataset.view)});
function saveWatch(){try{localStorage.setItem('marketWatch',JSON.stringify(watch));renderWatch();return true}catch{alert('浏览器未允许保存关注，请检查存储权限。');return false}}
function toggleStock(code){const i=watch.stocks.indexOf(code);if(i<0)watch.stocks.push(code);else watch.stocks.splice(i,1);saveWatch();if(selectedStock)byId('watchStock').textContent=watch.stocks.includes(selectedStock.ts_code)?'取消关注':'加入关注'}
function toggleSector(industry){const i=watch.sectors.indexOf(industry);if(i<0)watch.sectors.push(industry);else watch.sectors.splice(i,1);saveWatch();renderSectors()}
function stockTable(rows){return `<table><thead><tr><th>股票 / 代码</th><th>最新收盘</th><th>当日涨幅</th><th>近5日涨幅</th><th>量 / 前5日均量</th><th>流通市值(亿)</th><th>日线日期</th><th>关注</th></tr></thead><tbody>${rows.map(s=>`<tr><td><button data-stock="${esc(s.ts_code)}">${esc(s.name)}<br><small>${esc(s.ts_code)}</small></button></td><td>${fmt(s.close)}</td><td class="${color(s.pct_chg)}">${fmt(s.pct_chg)}${s.pct_chg==null?'':'%'}</td><td class="${color(s.ret_5d)}">${fmt(s.ret_5d)}${s.ret_5d==null?'':'%'}</td><td>${fmt(s.vol_ratio)}</td><td>${fmt(s.circ_mv_yi)}</td><td>${dateText(s.history_date)}${s.current?'':'<br><small>未纳入当日统计</small>'}</td><td><button data-watch="${esc(s.ts_code)}" aria-label="${watch.stocks.includes(s.ts_code)?'取消':'加入'}关注 ${esc(s.name)}">${watch.stocks.includes(s.ts_code)?'★':'☆'}</button></td></tr>`).join('')}</tbody></table>`}
document.body.addEventListener('click',event=>{const stock=event.target.closest('[data-stock]'),star=event.target.closest('[data-watch]'),sector=event.target.closest('[data-sector]'),sectorStar=event.target.closest('[data-sector-watch]');if(stock)selectStock(stock.dataset.stock,true);if(star){toggleStock(star.dataset.watch);renderStockList()}if(sector){byId('industryFilter').value=sector.dataset.sector;stockPage=0;renderStockList();showView('stockView')}if(sectorStar)toggleSector(sectorStar.dataset.sectorWatch)});
function renderStockList(){const q=byId('stockSearch').value.trim().toLowerCase(),industry=byId('industryFilter').value,key=byId('stockSort').value,cap=Number(byId('capFilter').value)||null;let rows=stocks.filter(s=>(!q||`${s.name} ${s.ts_code}`.toLowerCase().includes(q))&&(!industry||s.industry===industry)&&(!cap||(s.quote_current&&s.circ_mv_yi!=null&&s.circ_mv_yi>0&&s.circ_mv_yi<=cap)));rows.sort((a,b)=>Number(b.current)-Number(a.current)||(b[key]??-Infinity)-(a[key]??-Infinity)||a.ts_code.localeCompare(b.ts_code));const pages=Math.max(1,Math.ceil(rows.length/60));stockPage=Math.max(0,Math.min(stockPage,pages-1));byId('stockTable').innerHTML=rows.length?stockTable(rows.slice(stockPage*60,(stockPage+1)*60)):'<div class="empty">没有匹配股票。市值筛选仅使用当日有效市值。</div>';byId('stockCount').textContent=`${rows.length} 只 · 每页60只`;byId('pageLabel').textContent=`${stockPage+1} / ${pages}`;byId('prevPage').disabled=stockPage===0;byId('nextPage').disabled=stockPage===pages-1}
for(const id of ['stockSearch','industryFilter','stockSort','capFilter'])byId(id).addEventListener(id==='stockSearch'?'input':'change',()=>{stockPage=0;renderStockList()});
byId('prevPage').onclick=()=>{stockPage--;renderStockList()};byId('nextPage').onclick=()=>{stockPage++;renderStockList()};
function renderWatch(){byId('watchSectors').innerHTML=watch.sectors.length?'关注行业：'+watch.sectors.map(s=>`<button data-sector="${esc(s)}">${esc(s)}</button> <button data-sector-watch="${esc(s)}" aria-label="取消行业关注">×</button>`).join(' '):'<small>可在板块表中关注行业。</small>';const rows=watch.stocks.map(code=>stocks.find(s=>s.ts_code===code)||{ts_code:code,name:code,current:false});byId('watchTable').innerHTML=rows.length?stockTable(rows):'<div class="empty">还没有关注股票。在个股页或列表中点击星标即可加入。</div>'}
function renderSectors(){byId('sectorTable').innerHTML=`<table><thead><tr><th>行业</th><th>覆盖股票</th><th>近5日均涨幅</th><th>近5日中位数</th><th>当日上涨占比</th><th>关注</th></tr></thead><tbody>${sectors.map(s=>`<tr><td><button data-sector="${esc(s.industry)}">${esc(s.industry)}</button></td><td>${s.count}</td><td class="${color(s.ret_5d)}">${fmt(s.ret_5d)}%</td><td class="${color(s.median_5d)}">${fmt(s.median_5d)}%</td><td>${fmt(s.breadth,1)}%</td><td><button data-sector-watch="${esc(s.industry)}">${watch.sectors.includes(s.industry)?'★':'☆'}</button></td></tr>`).join('')}</tbody></table>`}
const chartBase={backgroundColor:'transparent',textStyle:{color:'#91a1af'},tooltip:{trigger:'axis'},grid:{left:65,right:24,top:24,bottom:40}};
function chart(id,option){const styleAxis=axis=>({...axis,axisLabel:{color:'#a2b2c0',...axis.axisLabel},axisLine:{lineStyle:{color:'#435563'},...axis.axisLine}});for(const key of ['xAxis','yAxis'])if(option[key])option[key]=Array.isArray(option[key])?option[key].map(styleAxis):styleAxis(option[key]);const instance=charts[id]||(charts[id]=echarts.init(byId(id)));instance.setOption(option,true);return instance}
function moving(rows,days){return rows.map((r,i)=>i+1<days?null:+(rows.slice(i-days+1,i+1).reduce((sum,v)=>sum+v[4],0)/days).toFixed(3))}
async function loadHistory(path){if(historyCache.has(path))return historyCache.get(path);let last;for(let attempt=0;attempt<3;attempt++){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{signal:controller.signal});if(!response.ok)throw Error('HTTP '+response.status);const rows=await response.json();if(!Array.isArray(rows)||!rows.length||!rows.every(r=>Array.isArray(r)&&r.length===6&&r.slice(1).every(Number.isFinite)))throw Error('日线格式不完整');historyCache.set(path,rows);return rows}catch(error){last=error}finally{clearTimeout(timer)}}throw last}
async function selectStock(code,open=true){const item=stocks.find(s=>s.ts_code===code);if(!item)return;selectedStock=item;const generation=++chartRequest;if(open)showView('stockView');byId('stockTitle').textContent=`${item.name} · ${item.ts_code}`;byId('stockSubtitle').textContent=`${item.industry} · 日线截止 ${dateText(item.history_date)} · ${item.history_days} 个交易日${item.current?'':' · 数据落后或本次未核验，不纳入当日池'}`;byId('watchStock').disabled=false;byId('watchStock').textContent=watch.stocks.includes(code)?'取消关注':'加入关注';byId('stockFacts').innerHTML=[['收盘价',fmt(item.close)],['当日涨幅',fmt(item.pct_chg)+'%'],['近5日涨幅',fmt(item.ret_5d)+'%'],['放量倍数',fmt(item.vol_ratio)],['换手率',fmt(item.turnover_rate)+'%'],['流通市值',fmt(item.circ_mv_yi)+' 亿']].map(([label,value])=>`<div><small>${label}</small><b>${value}</b></div>`).join('');charts.stockChart?.clear();byId('chartMessage').textContent='正在加载该股历史日线…';if(!item.history_path){byId('chartMessage').textContent='该股暂无可用免费历史日线。';return}try{const rows=await loadHistory(item.history_path);if(generation!==chartRequest)return;byId('chartMessage').textContent='';const dates=rows.map(r=>dateText(r[0]));chart('stockChart',{...chartBase,animation:false,legend:{data:['日线','MA5','MA10','MA20'],textStyle:{color:'#91a1af'},top:0},axisPointer:{link:[{xAxisIndex:'all'}]},tooltip:{trigger:'axis'},grid:[{left:62,right:22,top:36,height:'55%'},{left:62,right:22,top:'70%',height:'16%'}],xAxis:[{type:'category',data:dates,axisLabel:{show:false}},{type:'category',gridIndex:1,data:dates,axisLabel:{color:'#91a1af'}}],yAxis:[{scale:true,splitLine:{lineStyle:{color:'#25343f'}}},{scale:true,gridIndex:1,name:'手',splitLine:{show:false}}],dataZoom:[{type:'inside',xAxisIndex:[0,1],start:Math.max(0,100-100*90/rows.length),end:100},{type:'slider',xAxisIndex:[0,1],bottom:3,height:19,start:Math.max(0,100-100*90/rows.length),end:100}],series:[{name:'日线',type:'candlestick',data:rows.map(r=>[r[1],r[4],r[3],r[2]]),itemStyle:{color:'#f27b78',color0:'#62cab1',borderColor:'#f27b78',borderColor0:'#62cab1'}},...[5,10,20].map((days,i)=>({name:'MA'+days,type:'line',data:moving(rows,days),showSymbol:false,lineStyle:{width:1.3,color:['#e8ba69','#80b7ea','#ba9bdb'][i]}})),{name:'成交量(手)',type:'bar',xAxisIndex:1,yAxisIndex:1,data:rows.map(r=>({value:r[5],itemStyle:{color:r[4]>=r[1]?'#f27b78':'#62cab1'}}))}]});charts.stockChart.resize()}catch(error){if(generation!==chartRequest)return;byId('chartMessage').innerHTML='历史日线加载失败，当前未显示其他股票的数据。 <button id="retryHistory">重试</button>';byId('retryHistory').onclick=()=>selectStock(code,false)}}
byId('watchStock').onclick=()=>selectedStock&&toggleStock(selectedStock.ts_code);
function renderMarket(){byId('globalStatus').innerHTML=`<b>行情 ${dateText(summary.as_of)}</b><br>同日覆盖 ${summary.current_stocks} / ${summary.expected_stocks} 只`;byId('marketNotice').textContent=`${summary.age_days>4?'行情已超过4天，请核对休市安排与更新状态。':'免费盘后行情已接入。'} 观察池仅使用同日已核验日线；${summary.excluded_stocks} 只因停牌、日期落后或抓取未通过等原因未纳入当日统计。`;byId('marketCards').innerHTML=[['上涨 / 下跌',`${summary.advance} / ${summary.decline}`,`平盘 ${summary.flat} · 有效涨跌幅 ${summary.breadth_count} 只`],['覆盖成交额',fmt(summary.amount_yi,0)+' 亿',`${summary.amount_count} 只同日成交额，不补造缺失值`],['日线覆盖',fmt(summary.coverage,1)+'%',`${summary.current_stocks} 只已核验同日历史`],['量价观察池',window.__MARKET_DATA__.__PATTERN_ROWS__.filter(r=>r.status==='watch').length+' 只','整理观察阶段 · 转强不等于买入信号']].map(([label,value,note])=>`<div class="card"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');const top=sectors.filter(s=>s.industry!=='未分类'&&s.ret_5d!=null).slice(0,10).reverse();chart('sectorChart',{...chartBase,grid:{left:105,right:35,top:12,bottom:28},xAxis:{type:'value',axisLabel:{formatter:'{value}%'},splitLine:{lineStyle:{color:'#25343f'}}},yAxis:{type:'category',data:top.map(s=>s.industry)},series:[{type:'bar',data:top.map(s=>({value:s.ret_5d,itemStyle:{color:s.ret_5d>=0?'#f27b78':'#62cab1'}}))}]});chart('breadthChart',{...chartBase,xAxis:{type:'category',data:['上涨','下跌','平盘']},yAxis:{type:'value',splitLine:{lineStyle:{color:'#25343f'}}},series:[{type:'bar',barMaxWidth:70,data:[{value:summary.advance,itemStyle:{color:'#f27b78'}},{value:summary.decline,itemStyle:{color:'#62cab1'}},{value:summary.flat,itemStyle:{color:'#91a1af'}}]}]});byId('indexTable').innerHTML=`<table><thead><tr><th>指数</th><th>点位</th><th>涨跌幅</th><th>数据日期</th><th>状态</th></tr></thead><tbody>${summary.indices.map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.close)}</td><td class="${color(x.pct_chg)}">${fmt(x.pct_chg)}%</td><td>${dateText(x.trade_date)}</td><td>${x.closed?'收盘快照':'盘中快照'}</td></tr>`).join('')}</tbody></table>`}
const reviewFields={reviewPhase:'市场阶段',reviewAction:'明日动作',reviewPosition:'计划仓位（自行填写）',reviewConclusion:'一句话结论',reviewMainline:'主线行业',reviewBackup:'备选方向',reviewEffects:'赚钱与亏钱效应',reviewWatch:'观察对象',reviewTrigger:'触发条件',reviewCancel:'放弃条件',reviewLesson:'复盘沉淀'};
function reviewRecords(){const value=localRead('marketReviewV1',{});return typeof value==='object'&&!Array.isArray(value)?value:{}}
function loadReview(day){const record=reviewRecords()[day]||{};byId('reviewDate').value=day;Object.keys(reviewFields).forEach(key=>byId(key).value=record[key]??'');byId('reviewStatus').textContent=record.savedAt?'已保存 '+new Date(record.savedAt).toLocaleString('zh-CN'):'尚未保存';renderReviewHistory()}
function renderReviewHistory(){byId('reviewHistory').innerHTML=Object.keys(reviewRecords()).sort().reverse().map(day=>`<button data-review-date="${esc(day)}">${esc(day)}</button>`).join('');byId('reviewHistory').querySelectorAll('[data-review-date]').forEach(button=>button.onclick=()=>loadReview(button.dataset.reviewDate))}
function readReview(){const day=byId('reviewDate').value;return {...(reviewRecords()[day]||{}),date:day,...Object.fromEntries(Object.keys(reviewFields).map(key=>[key,byId(key).value.trim()]))}}
byId('reviewFields').innerHTML=Object.entries(reviewFields).map(([id,label])=>`<label for="${id}">${label}<textarea id="${id}"></textarea></label>`).join('');byId('reviewDate').onchange=()=>loadReview(byId('reviewDate').value);byId('saveReview').onclick=()=>{const record=readReview();if(!record.date){byId('reviewStatus').textContent='请先选择日期';return}try{record.savedAt=new Date().toISOString();localStorage.setItem('marketReviewV1',JSON.stringify({...reviewRecords(),[record.date]:record}));byId('reviewStatus').textContent='已保存';renderReviewHistory()}catch{byId('reviewStatus').textContent='保存失败，请检查浏览器存储权限或先导出'}};byId('exportReview').onclick=()=>{const record=readReview(),markdown=`# 市场复盘 ${record.date}\n\n`+Object.entries(reviewFields).map(([key,label])=>`## ${label}\n${record[key]||'未填写'}\n`).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+markdown],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`市场复盘-${record.date}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
byId('sourceDetails').innerHTML=`<p><b>${esc(summary.source)}</b> · 实际日线截止 ${dateText(summary.as_of)}<br><small>本次采集 ${esc(summary.generated_at)}；采集时间不等于行情日期。</small></p><p>自动更新：北京时间工作日 17:10 和 19:10。失败重试，保留完整缓存；覆盖不足时停止发布，行情过期时更新任务报错。</p><p>当前日线 ${summary.current_stocks} 只；请求成功核验 ${summary.checked_stocks} 只；本次错误 ${summary.errors.length} 项。部分股票停牌或缺失，统计范围不是全部上市公司。</p><ul class="source-list">${summary.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><a href="https://gu.qq.com/" target="_blank" rel="noopener">腾讯证券行情</a> · <a href="https://akshare.akfamily.xyz/data/stock/stock.html" target="_blank" rel="noopener">公开行情字段参考</a></p><details><summary>查看本次采集未通过项目</summary><pre style="white-space:pre-wrap">${esc(summary.errors.join('\n')||'无')}</pre></details>`;
byId('archiveLink').innerHTML=summary.archive_available?'<a href="archive/index.html">打开历史看板（资金及原日线主要截至 2026-08-20）</a>':'当前发布未包含历史看板，最新量价功能不受影响。';
byId('industryFilter').innerHTML+=[...new Set(stocks.map(s=>s.industry))].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');renderMarket();renderSectors();renderStockList();renderWatch();loadReview(dateText(summary.as_of));window.addEventListener('resize',()=>Object.values(charts).forEach(c=>c.resize()));
